#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const root=process.cwd();
const historyDir=path.join(root,'data/fag/historie');
const reportDir=path.join(root,'reports/historie-v5');
const domainId='his_migrasjon_minoritet_tilhorighet';
const conceptPath=path.join(historyDir,'concepts_historie_canonical_v5_5.json');
const theoryPath=path.join(historyDir,'theory_objects_historie_canonical_v5_5.json');
const targetPath=path.join(reportDir,'migrasjon-minoritet-tilhorighet-target-inventory.json');
const readJson=(file)=>JSON.parse(fs.readFileSync(file,'utf8'));
const writeJson=(file,value)=>fs.writeFileSync(file,`${JSON.stringify(value,null,2)}\n`);
fs.mkdirSync(reportDir,{recursive:true});

const C=(label,definition,type,related,distinguish,misuse,indicators,sources)=>({label,definition,concept_type:type,broader_concepts:[],narrower_concepts:[],related_concepts:related,distinguish_from:distinguish,common_misuse:[misuse],indicators,source_requirements:sources,status:'canonical_v5_5_curated'});
const conceptSpecs={
con_his_ankomst:C('ankomst','Ankomst er det daterbare tidspunktet og stedet der en person eller gruppe registreres, oppholder seg eller møter institusjoner etter en flytteetappe, uten at dette i seg selv dokumenterer varig bosetting.','migration_arrival_event_concept',['con_his_bosetting','con_his_ankomst_vs_varig_bosetting','con_his_mobilitet'],['con_his_opprinnelse'],'Å bruke første registrerte adresse eller innreisedato som bevis på varig bosted, migrasjonsmotiv eller sosial tilhørighet.',['datert innreise eller oppmøte','identifisert ankomststed og registreringsinstitusjon','sporbar videre flytting eller opphold'],['passasjer-, grense-, folkeregister- eller mottakskilde','senere adresse-, arbeid- eller husholdskilde som kontrollerer oppholdets varighet']),
con_his_ankomst_vs_varig_bosetting:C('ankomst versus varig bosetting','Skillet mellom ankomst og varig bosetting krever at første oppholdssted holdes adskilt fra senere stabil bolig, hushold, arbeid og lokal institusjonstilknytning.','arrival_settlement_distinction',['con_his_ankomst','con_his_bosetting','con_his_ankomstadresse_vs_varig_bosted'],['con_his_tilhorighet_vs_bosted'],'Å slå sammen hele migrasjonsforløpet til ett ankomststed og dermed skjule midlertidige opphold, intern flytting og flere bosettingsforsøk.',['minst to daterte oppholdspunkter','dokumentert varighet og husholdstilknytning','skille mellom mottak, midlertidighet og stabilisering'],['sammenhengende adresse- eller registerserie','arbeids-, skole- eller husholdskilde som dokumenterer faktisk etablering']),
con_his_ankomstadresse_vs_varig_bosted:C('ankomstadresse versus varig bosted','Ankomstadresse er den første dokumenterte adressen etter flytting, mens varig bosted krever senere kontinuitet i boligbruk, hushold, rettigheter og lokal hverdagspraksis.','address_residence_distinction',['con_his_ankomst','con_his_bosetting','con_his_hushold_vs_samboende_adresse'],['con_his_tilhorighet_vs_bosted'],'Å geokode en ankomstadresse som personens representative hjemsted uten å undersøke losji, institusjonsplassering, videreflytting og registreringsforsinkelse.',['første registrerte adresse','senere sammenhengende bostedsserie','dokumentert bolig- og husholdsbruk'],['adressebok, folkeregister eller mottaksjournal','leie-, skole-, arbeids- eller husholdskilder som bekrefter varighet']),
con_his_arbeidsmigrasjon:C('arbeidsmigrasjon','Arbeidsmigrasjon er flytting der forventet eller avtalt arbeid inngår som en dokumenterbar drivkraft, formidlet gjennom arbeidsgiver, marked, stat, familie eller rekrutteringsnettverk.','labour_migration_process',['con_his_migrasjonsdrivere','con_his_arbeidsmigrasjon_vs_arbeid_etter_ankomst','con_his_selvstendig_naering_vs_etnisk_nisje'],['con_his_intern_flytting_vs_grensekryssende_migrasjon'],'Å klassifisere alle migranter som senere arbeidet som arbeidsmigranter uten å dokumentere at arbeid inngikk i beslutningen eller rekrutteringskjeden før flyttingen.',['jobbtilbud, kontrakt eller rekruttering før flytting','arbeidsrelatert rute eller tillatelse','sammenheng mellom flytting og arbeidsmarked'],['kontrakter, arbeidstillatelser og arbeidsgiverarkiv','brev, intervjuer eller myndighetskilder som dokumenterer beslutningsforløpet']),
con_his_arbeidsmigrasjon_vs_arbeid_etter_ankomst:C('arbeidsmigrasjon versus arbeid etter ankomst','Skillet mellom arbeidsmigrasjon og arbeid etter ankomst avgjør om arbeid var en utløsningsfaktor for flyttingen eller en senere tilpasning etter en migrasjon drevet av andre forhold.','migration_motive_employment_distinction',['con_his_arbeidsmigrasjon','con_his_migrasjonsmotiv_vs_dokumentert_arsakskjede','con_his_ankomst'],['con_his_migrasjonsdrivere'],'Å lese senere yrke eller arbeidssted bakover som opprinnelig migrasjonsmotiv uten samtidige kilder til beslutningen.',['kronologi mellom flyttebeslutning og arbeid','dokumentert tilbud eller jobbsøk','alternative samtidige motiver'],['før-avreise-korrespondanse, kontrakt eller søknad','etter-ankomst arbeids- og intervjukilder som kontrollerer tidsrekkefølgen']),
con_his_avreisested_vs_opprinnelsesidentitet:C('avreisested versus opprinnelsesidentitet','Avreisested er siste dokumenterte opphold før en flytteetappe, mens opprinnelsesidentitet kan knyttes til flere steder, språk, slektskap og selvdefinisjoner over tid.','departure_origin_identity_distinction',['con_his_opprinnelse','con_his_identitet_vs_juridisk_status','con_his_transnasjonalisme'],['con_his_ankomst'],'Å gjøre siste avreisested til en fast etnisk eller nasjonal identitet og overse tidligere mobilitet, regionale tilhørigheter og aktørens egen betegnelse.',['dokumentert avreisested og tidspunkt','selvoppgitt eller relasjonell opprinnelse','flere mulige stedlige tilknytninger'],['reise-, pass- eller registerkilde','selvrepresentasjon, familiehistorie og tidligere bostedsserie']),
con_his_bedriftshistorie_vs_arbeider_og_migrasjonshistorie:C('bedriftshistorie versus arbeider- og migrasjonshistorie','Skillet undersøker forskjellen mellom virksomhetens institusjonelle fortelling og arbeidernes rekruttering, mobilitet, arbeidsvilkår, hushold og egne erfaringer.','company_worker_migration_distinction',['con_his_arbeidsmigrasjon','con_his_selvstendig_naering_vs_etnisk_nisje','con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring'],['con_his_institusjon_vs_hele_gruppen'],'Å bruke jubileumsbok eller bedriftsarkiv som fullstendig migrasjonshistorie uten å undersøke uregistrert arbeid, familier, konflikter og arbeidernes egne kilder.',['forskjell mellom ledelses- og arbeidstakerkilder','rekrutterings- og flyttemønster','arbeids- og husholdserfaringer utenfor bedriftens framstilling'],['bedriftsarkiv, lønnslister og personalregistre','fagforenings-, familie-, presse- og muntlige kontrollkilder']),
con_his_boligmangel_vs_dokumentert_diskriminering:C('boligmangel versus dokumentert diskriminering','Skillet mellom boligmangel og diskriminering krever at generell knapphet holdes adskilt fra ulik behandling knyttet til navn, hudfarge, språk, religion, opprinnelse eller status.','housing_shortage_discrimination_distinction',['con_his_diskriminering','con_his_bosetting','con_his_formell_rettighet_vs_reell_tilgang'],['con_his_fordom_vs_dokumentert_diskriminering'],'Å forklare alle avslag med diskriminering eller omvendt bruke generell boligmangel til å avvise dokumentert systematisk ulik behandling.',['sammenlignbare søkere eller henvendelser','uttalt eller statistisk mønster i avslag','kontroll for pris, tidspunkt og boligtype'],['annonser, søknader, korrespondanse og klagesaker','sammenlignbare markedsdata, tester eller intervjuer']),
con_his_bosetting:C('bosetting','Bosetting er prosessen der personer etablerer relativt stabil bolig, hushold, arbeid, skole- og tjenestetilknytning på et sted, frivillig eller gjennom offentlig plassering.','settlement_process',['con_his_ankomst','con_his_familienettverk_vs_offentlig_bosetting','con_his_tilhorighet_vs_bosted'],['con_his_ankomst_vs_varig_bosetting'],'Å tolke registrert adresse som ferdig bosetting uten å undersøke midlertidighet, videreflytting, boligkvalitet og faktisk bruk.',['varig eller gjentatt boligbruk','hushold, skole, arbeid eller tjenestetilknytning','dokumentert stabilitet og eventuell videreflytting'],['adresse- og folkeregisterserie, bolig- eller bosettingsvedtak','husholds-, skole-, arbeids- og muntlige kilder']),
con_his_diaspora_vs_permanent_utenforskap:C('diaspora versus permanent utenforskap','Diaspora betegner relasjoner, minner og institusjoner som forbinder spredte grupper og steder; det innebærer ikke automatisk permanent fremmedhet eller manglende lokal deltakelse.','diaspora_exclusion_distinction',['con_his_transnasjonalisme','con_his_tilhorighet','con_his_transnasjonalt_band_vs_manglende_lokal_tilhorighet'],['con_his_minorisering'],'Å bruke diaspora som synonym for isolasjon eller anta at transnasjonale bånd hindrer lokal tilhørighet og politisk deltakelse.',['organiserte forbindelser mellom flere steder','minne, praksis eller institusjoner på tvers av grenser','samtidig lokal deltakelse og stedstilknytning'],['forenings-, familie-, medie- og pengeoverføringskilder','lokale deltakelses- og selvrepresentasjonskilder']),
con_his_diskriminering:C('diskriminering','Diskriminering er dokumenterbar ulik behandling eller virkning knyttet til kategorisert tilhørighet, gjennom beslutninger, regler eller praksis i arbeid, bolig, utdanning, tjenester eller offentlighet.','discrimination_process',['con_his_rasisme','con_his_fordom_vs_dokumentert_diskriminering','con_his_formell_rettighet_vs_reell_tilgang'],['con_his_boligmangel_vs_dokumentert_diskriminering'],'Å bruke diskriminering som forklaring uten å identifisere beslutning, sammenligningsgrunnlag, institusjon og konsekvens, eller kreve eksplisitt rasistisk språk som eneste bevis.',['ulik behandling eller systematisk skjev virkning','identifisert kategori, arena og beslutning','sammenlignbar situasjon eller dokumentert mekanisme'],['vedtak, klager, korrespondanse og statistiske serier','sammenlignings-, intervjue- eller testkilder']),
con_his_enkeltstaende_konflikt_vs_institusjonelt_monster:C('enkeltstående konflikt versus institusjonelt mønster','Skillet krever at én konflikt holdes adskilt fra et gjentatt og organisatorisk forankret mønster i regler, rutiner, aktører eller utfall.','incident_institutional_pattern_distinction',['con_his_diskriminering','con_his_rasisme','con_his_institusjon_vs_hele_gruppen'],['con_his_motstand_vs_enhver_uenighet'],'Å generalisere fra én synlig sak til en hel institusjon eller avvise et mønster fordi hver sak har ulike detaljer.',['flere sammenlignbare hendelser','gjentatt regel, rutine eller aktørkjede','stabil skjevhet i utfall over tid'],['saksserier, instrukser og statistikk','enkeltmapper, intervjuer og kontrollgrupper som prøver mønsteret']),
con_his_etnisk_konsentrasjon_vs_segregasjon:C('etnisk konsentrasjon versus segregasjon','Etnisk konsentrasjon beskriver romlig samlokalisering, mens segregasjon krever dokumenterte barrierer, ulik tilgang eller institusjonelle mekanismer som opprettholder atskillelsen.','concentration_segregation_distinction',['con_his_bosetting','con_his_diskriminering','con_his_familienettverk_vs_offentlig_bosetting'],['con_his_gruppe_vs_administrativ_kategori'],'Å kalle ethvert nabolag med høy andel av en gruppe segregert uten å undersøke valg, boligmarked, nettverk, offentlig plassering og barrierer.',['romlig konsentrasjon målt med sammenlignbar geografi','dokumenterte adgangs- eller flyttebarrierer','varighet og ulikhet i ressurser eller tjenester'],['adresse-, bolig- og demografiske data','marked-, politikk- og intervjukilder som forklarer mekanismen']),
con_his_familiegjenforening_vs_opprinnelig_migrasjonsmotiv:C('familiegjenforening versus opprinnelig migrasjonsmotiv','Familiegjenforening er en senere flytting basert på familierelasjon og regelverk, og må skilles fra motivet og statusen til den første migranten i familien.','family_reunification_motive_distinction',['con_his_migrasjonsdrivere','con_his_familienettverk_vs_offentlig_bosetting','con_his_transnasjonalisme'],['con_his_arbeidsmigrasjon_vs_arbeid_etter_ankomst'],'Å gi alle familiemedlemmer samme migrasjonsmotiv eller beskrive familiegjenforening som rent privat uten å undersøke lov, tid, avhengighet og omsorg.',['identifisert referanseperson og relasjon','egen søknad, status og flyttedato','kronologisk skille mellom familiemedlemmers migrasjon'],['familiegjenforeningssøknader og vedtak','familie-, korrespondanse- og intervjukilder']),
con_his_familienettverk_vs_offentlig_bosetting:C('familienettverk versus offentlig bosetting','Skillet analyserer om bolig og sted ble funnet gjennom familie og bekjente eller bestemt og støttet av statlig eller kommunal bosettingspolitikk, ofte i kombinasjon.','family_network_public_settlement_distinction',['con_his_bosetting','con_his_familiegjenforening_vs_opprinnelig_migrasjonsmotiv','con_his_nettverk_vs_automatisk_solidaritet'],['con_his_ankomstadresse_vs_varig_bosted'],'Å tilskrive bosettingsmønsteret enten familievalg eller offentlig styring uten å rekonstruere tildeling, boligtilbud, avslag og videreflytting.',['dokumentert boligformidler eller vedtaksinstans','familie- og nettverkskontakt ved etablering','sporbar kombinasjon og senere boligkarriere'],['bosettingsvedtak, kommunale mapper og boligregistre','familiekorrespondanse og muntlige kilder']),
con_his_fordom_vs_dokumentert_diskriminering:C('fordom versus dokumentert diskriminering','Fordom er en holdning eller stereotyp forestilling, mens diskriminering krever at holdningen eller en institusjonell regel får dokumenterbar betydning for behandling, adgang eller utfall.','prejudice_discrimination_distinction',['con_his_diskriminering','con_his_rasisme','con_his_boligmangel_vs_dokumentert_diskriminering'],['con_his_rasialisering_vs_fast_identitet'],'Å bruke rasistisk språk som automatisk bevis for et bestemt diskriminerende utfall, eller avvise diskriminering når eksplisitt fordom ikke er nedskrevet.',['uttalt holdning eller stereotypi','konkret beslutning, praksis eller utfall','dokumentert forbindelse eller fravær av forbindelse'],['presse, taler, brev og intervjuer','saks-, sammenlignings- og statistikkilder som viser faktisk behandling']),
con_his_formell_rettighet_vs_reell_tilgang:C('formell rettighet versus reell tilgang','Skillet undersøker om en lovfestet rettighet faktisk kunne brukes, gitt dokumentkrav, økonomi, språk, informasjon, skjønn, geografi og institusjonell praksis.','formal_right_effective_access_distinction',['con_his_status','con_his_oppholdsstatus_vs_sosial_tilhorighet','con_his_diskriminering'],['con_his_statsborgerskap_vs_faktisk_medlemskap'],'Å anta at lik lovtekst ga lik tilgang eller bruke enkelttilgang som bevis på at strukturelle barrierer ikke eksisterte.',['formell regel og målgruppe','søknads-, saks- eller brukstall','dokumenterte barrierer, avslag og gjennomføring'],['lover, forskrifter og veiledninger','saksmapper, klager, brukerdata og intervjuer']),
con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring:C('fravær i arkivet versus fravær av erfaring','Arkivfravær betyr at en erfaring ikke er bevart, registrert eller søkbar i bestemte arkiver; det dokumenterer ikke at erfaringen eller aktøren manglet historisk betydning.','archival_silence_experience_distinction',['con_his_minne_vs_samtidig_dokumentasjon','con_his_selvrepresentasjon_vs_ekstern_omtale','con_his_minoritetshistorie'],['con_his_institusjon_vs_hele_gruppen'],'Å tolke manglende treff i myndighets- eller organisasjonsarkiv som bevis på passivitet, fravær eller enighet.',['identifisert arkivskaper og registreringsformål','kjent kassasjon, seleksjon eller katalogiseringsskjevhet','alternative materielle, muntlige eller private spor'],['arkivnøkler, journaler og bevaringshistorikk','muntlige, private, materielle og eksterne kontrollkilder']),
con_his_generasjon_vs_ensartet_erfaring:C('generasjon versus ensartet erfaring','Generasjon er en analytisk kohort knyttet til fødsel, migrasjonsfase eller familiesekvens, men personer i samme generasjon kan ha ulike statuser, kjønn, klasse, steder og erfaringer.','generation_heterogeneity_distinction',['con_his_tilhorighet','con_his_identitet_vs_juridisk_status','con_his_sprakbevaring_vs_uforandret_identitet'],['con_his_gruppe_vs_administrativ_kategori'],'Å tilskrive første, andre eller tredje generasjon én identitet eller integrasjonsbane uten å definere kohorten og undersøke intern variasjon.',['eksplisitt generasjonsdefinisjon','sammenlignbare livsløp og migrasjonstidspunkt','dokumentert variasjon innen kohorten'],['familie-, register- og livsløpsdata','intervjuer og institusjonskilder som viser ulike erfaringer']),
con_his_gruppe_vs_administrativ_kategori:C('sosial gruppe versus administrativ kategori','En sosial gruppe kan bygge på relasjoner og selvforståelse, mens en administrativ kategori er laget for registrering, rettigheter eller styring og kan samle personer som ikke oppfatter seg som én gruppe.','social_group_administrative_category_distinction',['con_his_juridisk_kategori_vs_selvvalgt_identitet','con_his_registrering_vs_noytral_beskrivelse','con_his_minoritetspolitikk'],['con_his_organisasjon_vs_hele_gruppen'],'Å bruke myndighetenes kategori som direkte navn på et homogent fellesskap eller lese endret statistikk som demografisk endring uten å kontrollere kategorirevisjon.',['dokumentert kategoridefinisjon og formål','selvorganisering eller relasjoner mellom kategoriserte personer','endring i klassifikasjon over tid'],['skjema, instrukser, statistikk og saksarkiv','selvrepresentasjon, organisasjons- og muntlige kilder']),
con_his_hushold_vs_samboende_adresse:C('hushold versus samboende adresse','Et hushold deler helt eller delvis økonomi, omsorg og hverdagsorganisering; personer registrert på samme adresse utgjør ikke nødvendigvis ett hushold.','household_co_residence_distinction',['con_his_bosetting','con_his_familienettverk_vs_offentlig_bosetting','con_his_ankomstadresse_vs_varig_bosted'],['con_his_status'],'Å rekonstruere familie og økonomisk fellesskap direkte fra adressebøker eller folkeregister uten å undersøke losji, framleie, institusjonsbolig og midlertidighet.',['samboende personer og tidsrom','delt økonomi, måltid, omsorg eller beslutning','intern relasjon og husholdsgrense'],['folketelling, bolig- og registerdata','leie-, familie-, budsjett- eller intervjukilder']),
con_his_identitet_vs_juridisk_status:C('identitet versus juridisk status','Identitet er situert selvforståelse og sosial tilskrivning, mens juridisk status er en formell kategori med bestemte rettigheter og plikter; de kan påvirke hverandre uten å være identiske.','identity_legal_status_distinction',['con_his_status','con_his_juridisk_kategori_vs_selvvalgt_identitet','con_his_tilhorighet'],['con_his_oppholdsstatus_vs_sosial_tilhorighet'],'Å bruke pass, statsborgerskap eller oppholdsstatus som fasit for etnisk, religiøs eller nasjonal identitet.',['selvbetegnelse og situert identifikasjon','formell status og regelverk','dokumentert samsvar, konflikt eller endring mellom dem'],['statusdokumenter og forvaltningssaker','selvrepresentasjon, intervjuer og organisasjonskilder']),
con_his_institusjon_vs_hele_gruppen:C('institusjon versus hele gruppen','En minoritetsinstitusjon representerer bestemte medlemmer, ledere og formål; den kan ikke uten videre brukes som talerør eller mål på erfaringene til alle som kategoriseres i gruppen.','institution_group_representation_distinction',['con_his_organisasjon_vs_hele_gruppen','con_his_gruppe_vs_administrativ_kategori','con_his_offentlig_synlighet_vs_politisk_innflytelse'],['con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring'],'Å generalisere fra en menighet, forening, skole eller butikk til en hel minoritetsbefolkning uten medlems-, rekkevidde- og konfliktdata.',['institusjonens mandat og medlemsgrunnlag','dokumentert aktivitet og geografisk rekkevidde','alternative institusjoner og ikke-medlemmer'],['vedtekter, medlemslister og møtebøker','befolknings-, intervjue- og konkurrerende organisasjonskilder']),
con_his_intern_flytting_vs_grensekryssende_migrasjon:C('intern flytting versus grensekryssende migrasjon','Intern flytting skjer innen samme statlige grense, mens grensekryssende migrasjon innebærer skifte av jurisdiksjon og ofte statusregime; begge kan inngå i samme mobilitetsforløp.','internal_international_migration_distinction',['con_his_mobilitet','con_his_arbeidsmigrasjon','con_his_transnasjonalisme'],['con_his_ankomst'],'Å behandle siste grensepassering som hele migrasjonshistorien og overse tidligere intern flytting, mellomstasjoner og senere mobilitet.',['komplett rute med daterte etapper','identifiserte jurisdiksjonsgrenser','status- og institusjonsendringer ved grensepassering'],['adresse-, reise- og grensedata','arbeids-, familie- og intervjukilder som rekonstruerer hele forløpet']),
con_his_juridisk_kategori_vs_selvvalgt_identitet:C('juridisk kategori versus selvvalgt identitet','Juridisk kategori fastsettes gjennom lov og forvaltning, mens selvvalgt identitet uttrykkes av personen eller fellesskapet og kan være flertydig, situert og skiftende.','legal_category_self_identification_distinction',['con_his_identitet_vs_juridisk_status','con_his_gruppe_vs_administrativ_kategori','con_his_registrering_vs_noytral_beskrivelse'],['con_his_status'],'Å gjengi en historisk juridisk betegnelse som aktørens egen identitet eller erstatte samtidens selvbetegnelse med dagens kategori uten forklaring.',['formell kategoridefinisjon','aktørens egen betegnelse i identifiserbar kontekst','dokumentert endring eller konflikt mellom kategoriene'],['lov, register og saksdokument','brev, forenings-, medie- og muntlige selvrepresentasjoner']),
con_his_migrasjonsdrivere:C('migrasjonsdrivere','Migrasjonsdrivere er økonomiske, politiske, miljømessige, familiære og institusjonelle forhold som endrer muligheter og press, men må kobles til konkrete beslutnings- og flyttekjeder.','migration_driver_concept',['con_his_arbeidsmigrasjon','con_his_migrasjonsmotiv_vs_dokumentert_arsakskjede','con_his_mobilitet'],['con_his_opprinnelse'],'Å liste fattigdom, krig eller arbeid som årsak uten å vise hvordan forholdet påvirket bestemte aktører, tidspunkt, ruter og alternativer.',['daterbar endring i press eller mulighet','mekanisme som når den flyttende aktøren','sammenheng med beslutning, rute og tidspunkt'],['økonomiske, politiske og miljømessige samtidige kilder','brev, søknader, intervjuer og sammenlignbare ikke-flyttere']),
con_his_migrasjonsmotiv_vs_dokumentert_arsakskjede:C('migrasjonsmotiv versus dokumentert årsakskjede','Et oppgitt migrasjonsmotiv er aktørens formulering i en bestemt situasjon; en dokumentert årsakskjede krever kronologi, mekanismer, alternativer og flere kilder.','migration_motive_causal_chain_distinction',['con_his_migrasjonsdrivere','con_his_arbeidsmigrasjon_vs_arbeid_etter_ankomst','con_his_familiegjenforening_vs_opprinnelig_migrasjonsmotiv'],['con_his_minne_vs_samtidig_dokumentasjon'],'Å gjøre ett retrospektivt svar til uttømmende årsak eller erstatte aktørens motiv med en strukturell forklaring uten forbindelsesledd.',['oppgitt motiv med kildekontekst','daterte hendelser og beslutningspunkter','alternative forklaringer og kontrollkilder'],['samtidige søknader, brev og administrative kilder','senere intervju og kontekstdata brukt kildekritisk']),
con_his_minne_vs_samtidig_dokumentasjon:C('minne versus samtidig dokumentasjon','Minner er senere situerte rekonstruksjoner av erfaring, mens samtidige dokumenter er produsert under andre interesser og begrensninger; ingen av dem er automatisk overordnet.','memory_contemporary_documentation_distinction',['con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring','con_his_selvrepresentasjon_vs_ekstern_omtale','con_his_migrasjonsmotiv_vs_dokumentert_arsakskjede'],['con_his_samtidig_betegnelse_vs_senere_sprakbruk'],'Å bruke avvik mellom minne og arkiv som bevis på at én kilde er falsk uten å undersøke produksjonstid, formål, taushet og senere erfaring.',['klart kilde- og erindringstidspunkt','sammenlignbare hendelser eller påstander','forklaring av samsvar, avvik og taushet'],['samtidige administrative og private dokumenter','muntlige historier med intervjukontekst og krysskontroll']),
con_his_minorisering:C('minorisering','Minorisering er en prosess der personer eller praksiser gjøres til avvikende og underordnet minoritet gjennom kategorisering, makt, institusjoner og offentlig representasjon.','minorization_process',['con_his_minoritetspolitikk','con_his_rasialisering','con_his_gruppe_vs_administrativ_kategori'],['con_his_minoritetshistorie'],'Å behandle minoritetsstatus som en fast egenskap ved gruppen uten å identifisere hvem som produserte skillet, gjennom hvilke arenaer og med hvilke konsekvenser.',['kategorisering mot en normativ majoritet','institusjonell eller offentlig forskjellssetting','ulik ressurs-, rettighets- eller representasjonsvirkning'],['lover, registre, skole-, medie- og forvaltningskilder','selvrepresentasjon og praksiskilder som viser respons og forhandling']),
con_his_minoritetshistorie:C('minoritetshistorie','Minoritetshistorie undersøker erfaringer, institusjoner, maktforhold og selvrepresentasjon hos grupper som er blitt minorisert, uten å redusere dem til statlige kategorier eller offerhistorie.','minority_history_field_concept',['con_his_minorisering','con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring','con_his_selvrepresentasjon_vs_ekstern_omtale'],['con_his_minoritetspolitikk'],'Å skrive minoritetshistorie bare fra myndighetsarkiv eller bare som diskrimineringshistorie og dermed overse hverdagsliv, interne forskjeller, organisering og aktørskap.',['flere kildeposisjoner og aktørnivåer','selvrepresentasjon og hverdagspraksis','makt, variasjon og endring innen gruppen'],['myndighets-, organisasjons-, familie- og materielle kilder','muntlige og minoritetsproduserte kilder med proveniens']),
con_his_minoritetspolitikk:C('minoritetspolitikk','Minoritetspolitikk er lover, programmer, registrering og institusjonell praksis som regulerer anerkjennelse, språk, religion, bosetting, vern, kontroll og deltakelse for kategoriserte grupper.','minority_policy_concept',['con_his_minorisering','con_his_minoritetsvern_vs_kontroll','con_his_registrering_vs_noytral_beskrivelse'],['con_his_minoritetshistorie'],'Å lese politiske mål som faktisk virkning eller omtale all politikk som enten vern eller undertrykking uten å undersøke blandede mekanismer og mottak.',['formell målgruppe og virkemiddel','ansvarlig institusjon og budsjett','dokumentert praktisering og konsekvens'],['lover, programmer, budsjetter og saksarkiv','lokale gjennomførings-, klage- og bruker-/gruppeskilder']),
con_his_minoritetsvern_vs_kontroll:C('minoritetsvern versus kontroll','Tiltak kan samtidig beskytte språk, rettigheter eller sikkerhet og gjøre grupper mer registrerbare, overvåkede eller avhengige; virkninger må analyseres separat.','minority_protection_control_distinction',['con_his_minoritetspolitikk','con_his_registrering_vs_noytral_beskrivelse','con_his_formell_rettighet_vs_reell_tilgang'],['con_his_status'],'Å klassifisere en ordning utelukkende etter uttalt verneformål eller kontrollkritikk uten å undersøke adgang, tvang, dataflyt og faktiske resultater.',['uttalt vern- og kontrollformål','registrering, vilkår eller tilsyn','dokumenterte gevinster, begrensninger og gruppers respons'],['lov, program, register- og tilsynsdokumenter','klager, brukerdata og minoritetsorganisasjoners kilder']),
con_his_mobilitet:C('mobilitet','Mobilitet er fysisk og sosial bevegelse mellom steder, arbeid, hushold og statuser, inkludert pendling, sesongflytting, tvang, retur og videre migrasjon.','mobility_process',['con_his_intern_flytting_vs_grensekryssende_migrasjon','con_his_ankomst','con_his_transnasjonalisme'],['con_his_bosetting'],'Å redusere mobilitet til permanent grensekryssing og dermed overse sirkulasjon, midlertidighet, pendling og tvungne bevegelser.',['daterte bevegelser mellom identifiserte steder','varighet, rytme og transport-/institusjonsramme','endring eller kontinuitet i arbeid, hushold og status'],['reise-, adresse-, arbeids- og grensedata','brev, intervjuer og materielle spor som viser faktisk bevegelse']),
con_his_motstand_vs_enhver_uenighet:C('motstand versus enhver uenighet','Motstand krever organisert eller gjentatt handling som utfordrer makt, regel eller representasjon; uenighet kan være privat, kortvarig og uten kollektiv strategi.','resistance_disagreement_distinction',['con_his_organisasjon_vs_hele_gruppen','con_his_offentlig_synlighet_vs_politisk_innflytelse','con_his_diskriminering'],['con_his_enkeltstaende_konflikt_vs_institusjonelt_monster'],'Å kalle enhver kritisk ytring motstand eller avvise lavsynlige former fordi de ikke tok form av offentlig protest.',['identifisert maktforhold og krav','gjentatt, kollektiv eller strategisk handling','reaksjon, risiko eller endring i praksis'],['forenings-, protest-, medie- og myndighetskilder','muntlige og private kilder som dokumenterer skjulte strategier']),
con_his_nettverk_vs_automatisk_solidaritet:C('nettverk versus automatisk solidaritet','Et nettverk er dokumenterte relasjoner som kan formidle informasjon, arbeid, bolig og omsorg; det garanterer ikke lik tilgang, tillit eller solidarisk handling.','network_solidarity_distinction',['con_his_familienettverk_vs_offentlig_bosetting','con_his_transnasjonalisme','con_his_selvstendig_naering_vs_etnisk_nisje'],['con_his_organisasjon_vs_hele_gruppen'],'Å anta at felles opprinnelse skaper ett hjelpenettverk eller at alle nettverksmedlemmer har like ressurser og forpliktelser.',['identifiserte relasjoner og utvekslinger','ulik posisjon, ressurs og tilgang','dokumentert hjelp, konflikt eller fravær av støtte'],['korrespondanse, medlems-, arbeid- og husholdsdata','intervjuer og konkrete formidlingsforløp']),
con_his_offentlig_synlighet_vs_politisk_innflytelse:C('offentlig synlighet versus politisk innflytelse','Offentlig synlighet er tilstedeværelse i medier, arrangementer og byrom, mens politisk innflytelse krever dokumentert adgang til beslutninger, agendaer eller ressursfordeling.','visibility_influence_distinction',['con_his_organisasjon_vs_hele_gruppen','con_his_selvrepresentasjon_vs_ekstern_omtale','con_his_motstand_vs_enhver_uenighet'],['con_his_synlig_bygg_vs_faktisk_aktivitet'],'Å bruke medieomtale, demonstrasjonsstørrelse eller synlig institusjon som bevis på politisk gjennomslag uten beslutningsspor.',['målbar offentlig eksponering','kontakt med beslutningsarena eller høring','sporbar endring i vedtak, agenda eller ressurs'],['presse-, arrangements- og organisasjonskilder','møte-, hørings-, lobby- og beslutningsdokumenter']),
con_his_oppholdsstatus_vs_sosial_tilhorighet:C('oppholdsstatus versus sosial tilhørighet','Oppholdsstatus er en juridisk adgang til å være i staten på bestemte vilkår; sosial tilhørighet skapes gjennom relasjoner, praksis, anerkjennelse og sted over tid.','residence_status_social_belonging_distinction',['con_his_status','con_his_tilhorighet','con_his_identitet_vs_juridisk_status'],['con_his_statsborgerskap_vs_faktisk_medlemskap'],'Å bruke midlertidig status som bevis på svak tilhørighet eller permanent status som bevis på sosial inkludering.',['formell status, varighet og vilkår','lokale relasjoner og institusjonsdeltakelse','selvopplevd og ekstern anerkjennelse'],['oppholdsvedtak og registerdata','arbeids-, skole-, organisasjons- og intervjukilder']),
con_his_opprinnelse:C('opprinnelse','Opprinnelse er en kontekstavhengig henvisning til fødested, familie, tidligere bosted, språk eller selvforståelse og må alltid spesifiseres framfor å behandles som én fast identitet.','origin_reference_concept',['con_his_avreisested_vs_opprinnelsesidentitet','con_his_identitet_vs_juridisk_status','con_his_samtidig_betegnelse_vs_senere_sprakbruk'],['con_his_ankomst'],'Å bruke landkode eller fødested som total forklaring på kultur, motiv, nettverk og senere tilhørighet.',['eksplisitt hvilken opprinnelsesdimensjon som brukes','kildens produsent og formål','dokumentert variasjon og endring over livsløpet'],['fødsels-, familie-, reise- og registerkilder','selvrepresentasjon og flere tidsfestede bosteds-/identitetskilder']),
con_his_organisasjon_vs_hele_gruppen:C('organisasjon versus hele gruppen','En organisasjon har medlemmer, ledelse og mandat og representerer ikke automatisk alle personer som deler juridisk, etnisk, religiøs eller migrasjonsrelatert kategori.','organization_group_distinction',['con_his_institusjon_vs_hele_gruppen','con_his_gruppe_vs_administrativ_kategori','con_his_offentlig_synlighet_vs_politisk_innflytelse'],['con_his_nettverk_vs_automatisk_solidaritet'],'Å gjengi en forenings uttalelse som gruppens samlede mening uten medlemsgrunnlag, intern debatt og alternative stemmer.',['vedtekter, medlemskap og mandat','ledelses- og beslutningsprosedyrer','alternative organisasjoner og ikke-organiserte aktører'],['foreningsarkiv, medlemslister og møtebøker','intervjuer, presse og konkurrerende organisasjonskilder']),
con_his_rasialisering:C('rasialisering','Rasialisering er prosessen der kropp, navn, språk, religion eller opprinnelse gis naturaliserte gruppeegenskaper og brukes til å forklare eller regulere forskjell og hierarki.','racialization_process',['con_his_rasisme','con_his_minorisering','con_his_rasialisering_vs_fast_identitet'],['con_his_religion_vs_etnisitet'],'Å behandle rasialisert kategori som faktisk biologisk eller uforanderlig identitet i stedet for å undersøke produsent, arena, tid og virkning.',['naturaliserende kategorisering av mennesker','kobling mellom tegn og antatte egenskaper','institusjonell eller sosial konsekvens'],['presse, vitenskap, skole-, politi- og forvaltningskilder','selvrepresentasjon og praksiskilder som viser respons og forhandling']),
con_his_rasialisering_vs_fast_identitet:C('rasialisering versus fast identitet','Rasialisering er en historisk tilskrivningsprosess, mens fast identitet antar stabile egenskaper; skillet gjør det mulig å undersøke skiftende kategorier og situasjoner.','racialization_fixed_identity_distinction',['con_his_rasialisering','con_his_identitet_vs_juridisk_status','con_his_samtidig_betegnelse_vs_senere_sprakbruk'],['con_his_juridisk_kategori_vs_selvvalgt_identitet'],'Å omtale rasialiserte grupper som tidløse enheter eller gjøre diskriminerende kategorier til nøytrale identitetsnavn.',['skiftende kategoribetegnelse og kriterier','identifisert arena og kategoriserende aktør','varierende selvbetegnelse og konsekvens'],['serielle medie-, register- og institusjonskilder','selvrepresentasjon og sammenligning mellom perioder og arenaer']),
con_his_rasisme:C('rasisme','Rasisme er ideer og praksiser som naturaliserer hierarkisk forskjell og legitimerer eller produserer ulik behandling, adgang, vold eller fordeling etter rasialiserte tegn.','racism_power_process',['con_his_rasialisering','con_his_diskriminering','con_his_fordom_vs_dokumentert_diskriminering'],['con_his_minorisering'],'Å redusere rasisme til individuell fiendtlighet eller bruke begrepet uten å dokumentere hierarki, institusjonell mekanisme og konsekvens.',['naturaliserende hierarki eller stereotypi','makt til å forme behandling eller ressurser','dokumentert ulikhet, eksklusjon eller vold'],['ideologiske, mediale og institusjonelle kilder','saks-, statistikk-, vitne- og gruppeskilder som viser virkning']),
con_his_registrering_vs_noytral_beskrivelse:C('registrering versus nøytral beskrivelse','Registrering er en institusjonell handling som velger kategorier, formål og datakrav og dermed former hvem som blir synlig og styrbar; den er ikke bare passiv beskrivelse.','registration_neutrality_distinction',['con_his_gruppe_vs_administrativ_kategori','con_his_minoritetspolitikk','con_his_juridisk_kategori_vs_selvvalgt_identitet'],['con_his_status'],'Å behandle registerkategorier som objektive samfunnsgrupper eller sammenligne tall over tid uten å kontrollere endrede skjema og registreringsformål.',['identifisert registereier og formål','kategori-, skjema- og instruksjonsendringer','konsekvens for rettigheter, statistikk eller kontroll'],['skjema, kodeverk, instrukser og registermetadata','saks- og selvrepresentasjonskilder som viser praktisk virkning']),
con_his_religion_vs_etnisitet:C('religion versus etnisitet','Religion viser til tros-, praksis- og institusjonstilknytning, mens etnisitet viser til relasjonell forestilling om avstamning, kultur og gruppe; de kan overlappe uten å være identiske.','religion_ethnicity_distinction',['con_his_identitet_vs_juridisk_status','con_his_rasialisering','con_his_gruppe_vs_administrativ_kategori'],['con_his_opprinnelse'],'Å bruke religiøs institusjon, navn eller opprinnelsesland som sikker indikator på etnisk identitet eller personlig tro.',['selvoppgitt eller praktisert religiøs tilknytning','selv- eller eksternt definert etnisitet','dokumentert overlapp, forskjell og endring'],['menighets-, forenings- og praksiskilder','selvrepresentasjon, intervjuer og kategori-/registerkilder']),
con_his_samtidig_betegnelse_vs_senere_sprakbruk:C('samtidig betegnelse versus senere språkbruk','Skillet holder historiske aktørers og institusjoners ord adskilt fra senere analytiske, juridiske og identitetspolitiske betegnelser, samtidig som begge forklares kildekritisk.','historical_later_terminology_distinction',['con_his_juridisk_kategori_vs_selvvalgt_identitet','con_his_rasialisering_vs_fast_identitet','con_his_opprinnelse'],['con_his_minne_vs_samtidig_dokumentasjon'],'Å modernisere historiske kategorier uten markering eller gjenta krenkende samtidsspråk som om det var nøytralt og selvvalgt.',['ordets produsent, dato og arena','samtidig betydning og maktfunksjon','senere omtolkning, avvisning eller gjenbruk'],['samtidige tekster, ordbøker, registre og debatter','senere selvrepresentasjon og begrepshistoriske studier']),
con_his_selvrepresentasjon_vs_ekstern_omtale:C('selvrepresentasjon versus ekstern omtale','Selvrepresentasjon er hvordan personer og organisasjoner framstiller egne erfaringer og krav, mens ekstern omtale produseres av myndigheter, medier eller andre aktører med egne formål.','self_external_representation_distinction',['con_his_minoritetshistorie','con_his_organisasjon_vs_hele_gruppen','con_his_fravaer_i_arkivet_vs_fravaer_av_erfaring'],['con_his_offentlig_synlighet_vs_politisk_innflytelse'],'Å gi selvrepresentasjon monopol på intern variasjon eller bruke ekstern omtale som direkte beskrivelse av gruppens identitet og praksis.',['identifisert avsender og publikum','framstillingsformål og sjanger','samsvar, konflikt og taushet mellom posisjonene'],['minoritetspresse, brev, forenings- og muntlige kilder','myndighets-, presse- og institusjonskilder brukt komparativt']),
con_his_selvstendig_naering_vs_etnisk_nisje:C('selvstendig næring versus etnisk nisje','Selvstendig næring er en eier- og arbeidsform; en etnisk nisje krever dokumentert konsentrasjon, nettverksrekruttering, marked og kategorisering knyttet til en gruppe.','self_employment_ethnic_niche_distinction',['con_his_arbeidsmigrasjon','con_his_nettverk_vs_automatisk_solidaritet','con_his_bedriftshistorie_vs_arbeider_og_migrasjonshistorie'],['con_his_etnisk_konsentrasjon_vs_segregasjon'],'Å kalle enhver migrantdrevet virksomhet en etnisk nisje eller anta at nettverket er solidarisk og lukket uten eier-, arbeids- og kundedata.',['eierskap og arbeidsform','gruppekonsentrasjon i rekruttering eller marked','dokumenterte nettverks- og barrieremekanismer'],['bedrifts-, skatt-, arbeids- og bransjeregister','intervjuer, kundedata og sammenlignbare virksomheter']),
con_his_sprakbevaring_vs_uforandret_identitet:C('språkbevaring versus uforandret identitet','Språkbevaring er fortsatt eller gjenopptatt bruk, undervisning og overføring av språk; det innebærer ikke at identitet, praksis og betydning forblir uendret.','language_retention_identity_distinction',['con_his_generasjon_vs_ensartet_erfaring','con_his_tilhorighet','con_his_religion_vs_etnisitet'],['con_his_opprinnelse'],'Å bruke språkbruk som direkte mål på autentisk eller uforandret gruppeidentitet og overse flerspråklighet, skifte og strategisk bruk.',['språkbruk i spesifisert arena og generasjon','overførings- og undervisningspraksis','endret funksjon, kompetanse og identitetsbetydning'],['skole-, menighets-, medie- og familiekilder','intervjuer og språkbruksdata fra flere arenaer og tidspunkter']),
con_his_statsborgerskap_vs_faktisk_medlemskap:C('statsborgerskap versus faktisk medlemskap','Statsborgerskap gir formell statsrettslig status, mens faktisk medlemskap også avhenger av rettighetsbruk, anerkjennelse, deltakelse og adgang til institusjoner.','citizenship_membership_distinction',['con_his_status','con_his_formell_rettighet_vs_reell_tilgang','con_his_oppholdsstatus_vs_sosial_tilhorighet'],['con_his_tilhorighet'],'Å anta at statsborgerskap avslutter eksklusjon eller at manglende statsborgerskap betyr fravær av lokalt og politisk medlemskap.',['formell statsborgerstatus og dato','praktisk rettighets- og institusjonsadgang','deltakelse, anerkjennelse og eksklusjon'],['statsborgerregistre, lover og enkeltsaker','valg-, arbeids-, organisasjons- og intervjukilder']),
con_his_status:C('juridisk migrasjonsstatus','Juridisk migrasjonsstatus er en tidsavgrenset forvaltningskategori som regulerer opphold, arbeid, familie, vern og adgang til tjenester og kan endres gjennom vedtak, klage og livshendelser.','migration_legal_status_concept',['con_his_oppholdsstatus_vs_sosial_tilhorighet','con_his_formell_rettighet_vs_reell_tilgang','con_his_statsborgerskap_vs_faktisk_medlemskap'],['con_his_identitet_vs_juridisk_status'],'Å behandle status som permanent identitet eller gjengi én registerkode uten gyldighetsperiode, vilkår og pågående sak.',['presis statuskategori og hjemmel','gyldighetsperiode, vilkår og rettigheter','endring, klage eller overgang mellom statuser'],['vedtak, lovverk og saksjournal','arbeids-, tjeneste- og personkilder som viser praktiske følger']),
con_his_synlig_bygg_vs_faktisk_aktivitet:C('synlig bygg versus faktisk aktivitet','Et synlig menighets-, forenings- eller næringsbygg dokumenterer et fysisk anker, men aktivitet, medlemskap og betydning må påvises gjennom bruk, tid og organisasjon.','visible_building_activity_distinction',['con_his_institusjon_vs_hele_gruppen','con_his_offentlig_synlighet_vs_politisk_innflytelse','con_his_selvrepresentasjon_vs_ekstern_omtale'],['con_his_bosetting'],'Å bruke dagens skilt eller bygg som bevis på kontinuerlig historisk aktivitet eller representativitet for hele gruppen.',['datert eierskap, leie eller bruk','arrangement, medlemskap eller åpningstid','funksjonsendring og faktisk rekkevidde'],['eiendoms-, byggesaks-, forenings- og programkilder','observasjon, presse, intervjuer og regnskap som viser bruk']),
con_his_tilhorighet:C('tilhørighet','Tilhørighet er en historisk relasjon mellom personer, steder, mennesker og institusjoner, uttrykt gjennom praksis, rettigheter, minner, anerkjennelse og selvforståelse.','belonging_relational_concept',['con_his_tilhorighet_vs_bosted','con_his_oppholdsstatus_vs_sosial_tilhorighet','con_his_transnasjonalisme'],['con_his_status'],'Å behandle tilhørighet som en målbar indre følelse alene eller anta at den er eksklusiv til ett sted og lik for hele gruppen.',['selvuttrykt sted- eller fellesskapsrelasjon','gjentatt deltakelse og sosial anerkjennelse','rettighets-, minne- eller praksisforankring'],['intervjuer, brev, organisasjons- og hverdagskilder','register- og institusjonskilder brukt som kontekst, ikke fasit']),
con_his_tilhorighet_vs_bosted:C('tilhørighet versus bosted','Bosted er en fysisk og administrativ lokalisering, mens tilhørighet krever relasjoner, praksis, minner og anerkjennelse og kan knytte en person til flere steder.','belonging_residence_distinction',['con_his_tilhorighet','con_his_bosetting','con_his_ankomstadresse_vs_varig_bosted'],['con_his_oppholdsstatus_vs_sosial_tilhorighet'],'Å bruke registrert bosted som direkte mål på sosial tilhørighet eller tolke videreflytting som fravær av lokal betydning.',['dokumentert bosted og varighet','selvrepresenterte og praktiserte stedstilknytninger','flere samtidige eller historiske tilhørigheter'],['adresse- og boligdata','intervjuer, organisasjons-, familie- og minnekilder']),
con_his_transnasjonalisme:C('transnasjonalisme','Transnasjonalisme er vedvarende praksiser og relasjoner som forbinder personer, hushold, organisasjoner og institusjoner på tvers av statsgrenser gjennom omsorg, penger, politikk, religion, medier og mobilitet.','transnationalism_concept',['con_his_mobilitet','con_his_tilhorighet','con_his_diaspora_vs_permanent_utenforskap'],['con_his_intern_flytting_vs_grensekryssende_migrasjon'],'Å bruke enhver utenlandsk kontakt som transnasjonalisme eller anta at grenseoverskridende bånd svekker lokal integrasjon og tilhørighet.',['gjentatt relasjon mellom minst to land/steder','konkret utveksling eller institusjonell praksis','varighet, aktører og betydning på begge sider'],['reise-, penge-, kommunikasjons- og organisasjonskilder','husholds-, intervjue- og institusjonskilder fra flere steder']),
con_his_transnasjonalt_band_vs_manglende_lokal_tilhorighet:C('transnasjonalt bånd versus manglende lokal tilhørighet','Transnasjonale bånd og lokal tilhørighet kan eksistere samtidig; skillet krever at praksis på tvers av grenser ikke tolkes som fravær av relasjoner og medlemskap der personen bor.','transnational_local_belonging_distinction',['con_his_transnasjonalisme','con_his_tilhorighet','con_his_diaspora_vs_permanent_utenforskap'],['con_his_tilhorighet_vs_bosted'],'Å bruke pengeoverføringer, reiser eller utenlandske medier som bevis på manglende lojalitet, integrasjon eller lokal deltakelse.',['dokumentert grenseoverskridende praksis','dokumentert lokal relasjon og deltakelse','aktørens egen forståelse av flere tilhørigheter'],['reise-, penge-, medie- og familie-/organisasjonskilder','lokale arbeid-, skole-, nabo- og intervjukilder'])
};

const target=readJson(targetPath);
const targetIds=[...target.concept_ids].sort();
const specIds=Object.keys(conceptSpecs).sort();
if(JSON.stringify(targetIds)!==JSON.stringify(specIds))throw new Error(`Concept mismatch: ${JSON.stringify({targetIds,specIds})}`);
const concepts=readJson(conceptPath);const conceptById=new Map(concepts.map((item)=>[item.concept_id,item]));const curatedConcepts=[];
for(const[id,spec]of Object.entries(conceptSpecs)){const item=conceptById.get(id);if(!item)throw new Error(`Missing concept ${id}`);const previousLabel=item.label;Object.assign(item,spec);curatedConcepts.push({concept_id:id,previous_label:previousLabel,label:item.label,concept_type:item.concept_type});}
writeJson(conceptPath,concepts);

const theorySpecs={
theory_his_migrasjonsdrivere_flyttestrommer:{definition:'Rekonstruerer migrasjon som flerleddede forløp der strukturelle drivere, husholdsbeslutninger, rekruttering, tvang, ruter, mellomstasjoner og statusregimer virker sammen uten at ett oppgitt motiv alene blir årsaksforklaring.',limitations:['Makroforhold som krig, lønnsnivå eller lovendring må kobles til konkrete aktører og beslutningsledd før de kan kalles årsak.','Registrert grensepassering eller ankomst skjuler ofte intern flytting, mellomstasjoner, retur og videre migrasjon.','Retrospektive motiver må kontrolleres mot samtidige kilder uten å avvise minnets erfaring og mening.']},
theory_his_ankomst_bosetting_bolig:{definition:'Analyserer bosetting som en sekvens fra ankomst og midlertidig adresse til boligkarriere, hushold, offentlig plassering, familienettverk og mulig videreflytting, formet av marked og ulik adgang.',limitations:['Første adresse dokumenterer ikke varig bosted, hushold eller representativt nabolag.','Etnisk konsentrasjon må ikke kalles segregasjon uten dokumenterte barrierer og sammenlignbar romlig analyse.','Boligmangel og diskriminering kan virke samtidig og må skilles med markeds-, saks- og sammenligningskilder.']},
theory_his_arbeid_nettverk_naring:{definition:'Undersøker hvordan arbeidsgivere, tillatelser, familie- og rekrutteringsnettverk, selvstendig næring og bolig koblet migrasjon til konkrete arbeidsmarkeder og virksomheter.',limitations:['Senere arbeid beviser ikke at arbeid var det opprinnelige migrasjonsmotivet.','Nettverk må dokumenteres som konkrete relasjoner og kan ikke antas å gi automatisk solidaritet eller lik adgang.','Migrantdrevet selvstendig næring er ikke uten videre en etnisk nisje; konsentrasjon, marked og barrierer må påvises.']},
theory_his_statsborgerskap_status_rettigheter:{definition:'Analyserer statsborgerskap og oppholdsstatus som skiftende juridiske posisjoner som åpner og begrenser arbeid, familie, bolig, vern og politiske rettigheter, men ikke alene avgjør faktisk medlemskap og tilhørighet.',limitations:['Formell status må dateres og knyttes til konkret hjemmel, vilkår og rettighetsinnhold.','Lovfestet rettighet dokumenterer ikke reell tilgang når språk, skjønn, økonomi og institusjonell praksis skaper barrierer.','Statsborgerskap må ikke brukes som fasit for identitet, sosial inkludering eller fravær av diskriminering.']},
theory_his_minoritetspolitikk_kategorisering_registrering:{definition:'Undersøker hvordan minoritetspolitikk produserer målgrupper gjennom navn, registre, statistikk, språk- og institusjonstiltak, og hvordan vern, kontroll og kategorisering får ulike praktiske virkninger.',limitations:['Administrative kategorier er laget for bestemte styringsformål og kan ikke leses som homogene sosiale grupper.','Endringer i statistikk kan skyldes nye skjema, kriterier og registreringspraksiser snarere enn befolkningsendring.','Et vernetiltak kan samtidig øke registrering og kontroll; formål og virkning må analyseres separat.']},
theory_his_sprak_religion_institusjoner:{definition:'Analyserer språk, religion og minoritetsinstitusjoner som skiftende praksiser og infrastrukturer for undervisning, ritual, medier, omsorg og organisering mellom generasjoner og steder.',limitations:['Synlig bygg eller formell institusjon dokumenterer ikke kontinuerlig aktivitet, medlemskap eller representativitet.','Religion, etnisitet, språk og nasjonal opprinnelse må ikke brukes som gjensidige stedfortredere.','Språkbevaring innebærer ikke uforandret identitet; funksjon, kompetanse og generasjonsbruk kan endres.']},
theory_his_familie_transnasjonale_band:{definition:'Rekonstruerer hushold og familie som relasjoner på tvers av bosteder og grenser gjennom omsorg, penger, kommunikasjon, reiser, familiegjenforening og skiftende juridiske vilkår.',limitations:['Personer på samme adresse utgjør ikke automatisk ett økonomisk og omsorgsmessig hushold.','Familiemedlemmer kan ha ulike migrasjonsmotiver, tidspunkter og statuser og må ikke gis én felles migrasjonshistorie.','Transnasjonale bånd må ikke tolkes som manglende lokal tilhørighet eller permanent utenforskap.']},
theory_his_diskriminering_rasisme_ekskludering:{definition:'Analyserer rasisme, rasialisering og diskriminering gjennom ideer, kategorier, beslutninger, institusjonelle rutiner og skjeve utfall, med eksplisitt skille mellom fordom, enkelthendelse og varig mønster.',limitations:['Ubehagelig eller rasistisk språk beviser ikke alene et bestemt diskriminerende utfall, men fravær av eksplisitt språk utelukker heller ikke diskriminering.','Enkeltstående konflikt må ikke generaliseres til institusjonelt mønster uten serier, regler eller gjentatte utfall.','Generell knapphet i bolig eller arbeid må kontrolleres før ulik behandling tilskrives eller avvises som diskriminering.']},
theory_his_organisering_motstand_offentlighet:{definition:'Undersøker foreninger, medier, møteplasser, protest og hverdagsmotstand som former minoriteters selvrepresentasjon og krav, samtidig som organisasjoner og synlige aktører ikke likestilles med hele gruppen.',limitations:['En organisasjons uttalelse kan ikke gjøres til gruppens samlede mening uten medlemsgrunnlag og alternative stemmer.','Offentlig synlighet må skilles fra dokumentert politisk innflytelse på vedtak, agenda og ressurser.','Enhver uenighet er ikke motstand, men lavsynlige strategier må heller ikke avvises fordi de mangler offentlig protestform.']},
theory_his_tilhorighet_identitet_minne:{definition:'Analyserer tilhørighet og identitet som relasjonelle og situerte prosesser knyttet til steder, status, språk, familie, minner og anerkjennelse, med flere samtidige og skiftende medlemskap.',limitations:['Bosted, oppholdsstatus, statsborgerskap og opprinnelsesland kan ikke brukes som direkte mål på identitet eller tilhørighet.','Generasjonskategorier må defineres og kan ikke tilskrives ensartede erfaringer eller utviklingsbaner.','Minner og samtidige dokumenter er produsert under ulike vilkår; avvik må forklares kildekritisk framfor å rangere kildetypene automatisk.']}
};
const targetTheoryIds=[...target.theory_ids].sort();const specTheoryIds=Object.keys(theorySpecs).sort();if(JSON.stringify(targetTheoryIds)!==JSON.stringify(specTheoryIds))throw new Error(`Theory mismatch: ${JSON.stringify({targetTheoryIds,specTheoryIds})}`);
const theories=readJson(theoryPath);const theoryById=new Map(theories.map((item)=>[item.theory_id,item]));for(const[id,spec]of Object.entries(theorySpecs)){const item=theoryById.get(id);if(!item)throw new Error(`Missing theory ${id}`);Object.assign(item,spec,{status:'canonical_v5_5_curated',evidence_ready:false});}writeJson(theoryPath,theories);

const run=(name,command,args)=>{const result=spawnSync(command,args,{cwd:root,encoding:'utf8'});const output=`$ ${command} ${args.join(' ')}\n${result.stdout||''}${result.stderr||''}`;fs.writeFileSync(path.join(reportDir,name),output);if(result.status!==0)throw new Error(`${command} ${args.join(' ')} failed with ${result.status}`);};
run('migrasjon-minoritet-tilhorighet-domain-validation.log',process.execPath,['tools/validate-historie-domain.mjs',domainId]);
run('migrasjon-minoritet-tilhorighet-v5-validation.log',process.execPath,['tools/validate-historie-v5.mjs','--write']);
run('migrasjon-minoritet-tilhorighet-quiz-context.log','npm',['run','quiz:context']);
run('migrasjon-minoritet-tilhorighet-knowledge-canonical.log','npm',['run','knowledge:canonical:write']);
run('migrasjon-minoritet-tilhorighet-quiz-production-context-audit.log','npm',['run','audit:quiz-production-context']);
run('migrasjon-minoritet-tilhorighet-quiz-progression-audit.log','npm',['run','audit:quiz-progression']);
run('migrasjon-minoritet-tilhorighet-quiz-theory-binding-audit.log','npm',['run','audit:quiz-theory-binding']);
run('migrasjon-minoritet-tilhorighet-quiz-production-test.log','npm',['run','test:quiz-production']);
const readiness=readJson(path.join(reportDir,'historie-v5-5-readiness.json'));const domain=readiness.domains.find((item)=>item.domain_id===domainId);if(!domain?.freeze_ready)throw new Error(JSON.stringify(domain));
writeJson(path.join(reportDir,'migrasjon-minoritet-tilhorighet-curation-index.json'),{generated_at:new Date().toISOString(),domain_id:domainId,curated_concepts:curatedConcepts,curated_theory_ids:Object.keys(theorySpecs)});
writeJson(path.join(reportDir,'migrasjon-minoritet-tilhorighet-curation-readiness.json'),{generated_at:new Date().toISOString(),domain_id:domainId,curated_concept_ids:Object.keys(conceptSpecs),curated_theory_ids:Object.keys(theorySpecs),domain_readiness:domain,global_status:readiness.status,v6_allowed:readiness.v6_allowed,quality_issue_totals:readiness.quality_issue_totals,next_gate:'Continue individual curation of the remaining V5.5 domains before global freeze and V6 activation.'});
fs.rmSync(targetPath,{force:true});
const restore=spawnSync('git',['checkout','--','data/places/places_index.json','data/quiz/production_context/by/deichman_bjorvika.json'],{cwd:root,encoding:'utf8'});if(restore.status!==0)throw new Error(restore.stderr||'Failed to restore generated place files');
